        self.assertFalse(balanced('(]'))

    def test_unclosed(self):
        self.assertFalse(balanced('(()'))

    def test_extra_closer(self):
        self.assertFalse(balanced('())('))

    def test_crossed_nesting(self):
        self.assertFalse(balanced('([)]'))

    def test_single_closer(self):
        self.assertFalse(balanced('}'))


